{"command":"python3 -c "
import json, glob
for f in sorted(glob.glob('/tmp/mf-req-*.json')):
    d = json.load(open(f))
    slug = f.split('mf-req-')[1][:-5]
    esc = d.get('escrow') or {}
    funded = esc.get('funded') or esc.get('funded_usd') or ''
    pc = d.get('payout_curve') or []
    total = sum((p.get('usd') or p.get('amount_usd') or 0) for p in pc) if isinstance(pc, list) else ''
    fee = d.get('entry_fee') or d.get('entryFee')
    dl = d.get('deliverables') or {}
    hts = d.get('how_to_submit') or {}
    strict = hts.get('strict_transcripts')
    fields = []
    if isinstance(dl, dict):
        fields = list(dl.keys())
    elif isinstance(dl, list):
        fields = [str(x)[:40] for x in dl]
    q = d.get('quota') or {}
    pre = d.get('prerequisites') or (d.get('bundle', {}) or {}).get('competition', {}).get('prerequisites') or []
    pre_req = [p.get('label') or p.get('name') for p in pre if isinstance(p, dict) and p.get('required')]
    print(f\"== {slug} | escrow={funded} | payout_total~{total} | fee={fee} | strict={strict} | deliverables={fields} | quota={q} | prereq_required={pre_req}\")
""}
